// ================= v5.55: MODOS ONLINE NUEVOS =================
// Sergio eligió de las ideas: conquista de territorios, caravana con asaltos online, festival en vivo semanal,
// restaurante compartido, correo con regalos, apuestas en los duelos del coliseo y «cazar a la presa».
// (No la mazmorra por turnos, ni la ciudad que crece, ni las mascotas que trabajan.) Todo se juega en el mapa; las
// ventanas solo informan o eligen. Todo sale en ▦ Atajos › 🌐 Modos online y en la Lupa › Sistemas.
// Ya existían y se amplían (no se repiten): la caravana escoltada de los caravaneros (asaltantes NPC), las fichas del
// Coliseo y su tienda, el Cartero del cielo (oficio) y los gremios.
// Firebase (reglas nuevas en docs/firebase_rules.json, Sergio tiene que pegarlas): ev/tr territorios, ev/fe votos
// del festival, ev/rs restaurantes, ml correo.
SAVEKEYS.push('terrTax', 'terrPts', 'bnd', 'bndWins', 'feN', 'feLast', 'feVote', 'feWin', 'feBest', 'rest', 'restC', 'mailBook', 'mlGot', 'mlSeen', 'betW', 'betDay', 'preyWin', 'preyHunt');
const V6R = (g, x, y, w, h, c) => { g.fillStyle = c; g.fillRect(Math.round(x), Math.round(y), w, h); };
