  if (Array.isArray(pr.x6)) for (const h of pr.x6) { if (!h || !(h.s > (r.x6Seen || 0))) continue; mx = Math.max(mx, h.s); if (first || h.to !== NET.myId || r.map !== P.map || P.dead) continue; const f = X6_RECV[h.k]; if (f) try { f(r, clamp(+h.d || 0, 0, 100)); } catch (e) { console.warn(e); } }
