{ const _pd = placeDiveSpots; placeDiveSpots = function (W) { _pd(W); try { for (const t of TOWNS) { const [x, y] = freeTileNear(W, Math.round((t.x0 + t.x1) / 2) - 4, t.y0 + 4); addObj(W, 'furn', x, y, { f: 'terr_flag', fp: [[0, 0]], solid: false, xact: 'terr', tz: t.k }); TR6.flag[t.k] = { x: x * 16 + 8, y: y * 16 + 8 };
  v6Poi(W, x, y, () => { const o = terrOwner(t.k); return '🏳 ' + L2('Territorio de ', 'Territory of ') + t.n + (o ? ' · ' + o.ic + ' [' + o.tg + '] ' + o.n : ' · ' + L2('sin dueño', 'no owner')); }); } } catch (e) { console.warn(e); } }; }
XACT.terr = [o => '🏳 ' + L2('Estandarte de ', 'Banner of ') + terrName(o.tz), 'star', o => terrOpen(o.tz)];
// el nombre del gremio dueño encima del estandarte y el color de su bandera
