  P.terrPts = (P.terrPts || 0) + pts; const c = P.clan, gold = 20000 + P.lv * 200; P.gold += gold; banner('🏳 ' + L2('¡Estandarte asaltado!', 'Banner assaulted!'), '+' + pts + L2(' puntos para tu gremio · +', ' points for your guild · +') + fmt(gold) + L2(' de oro', ' gold')); sfx('level'); markDirty(true);
